  1	/* ============================================================
  2	   views/config.js — Configuration view coordinator
  3	   Section 4d of the MCP Server Dashboard SPA
  4	   Depends on: API, UI, escapeHtml, showLoading, showError
  5	   Tab modules: config-model-registry.js, config-persona-models.js (load first)
  6	   ============================================================ */
  7	
  8	/* ── Module-level state ──────────────────────────────────── */
  9	
 10	var configActiveTab = 'general';
 11	
 12	/* Dirty-tracking: keyed by tab name, true when the tab has unsaved changes */
 13	var configDirty = {
 14	  general: false,
 15	  personaModels: false,
 16	  modelRegistry: false
 17	};
 18	
 19	/* ── Entry point ─────────────────────────────────────────── */
 20	
 21	function renderConfig(app) {
 22	  showLoading(app);
 23	
 24	  Promise.all([
 25	    API.getConfig(),
 26	    API.getModels ? API.getModels() : Promise.resolve([]),
 27	    API.getPersonas ? API.getPersonas() : Promise.resolve([]),
 28	    API.getAssignments ? API.getAssignments() : Promise.resolve([])
 29	  ]).then(function (results) {
 30	    renderConfigPage(app, results[0], results[1], results[2], results[3]);
 31	  }).catch(function (err) {
 32	    showError(app, 'Failed to load configuration: ' + (err.message || String(err)));
 33	  });
 34	}
 35	
 36	/* ── Page scaffold ───────────────────────────────────────── */
 37	
 38	function renderConfigPage(app, config, models, personas, assignments) {
 39	  /* Reset dirty flags and all tab module state — fresh server data loaded. */
 40	  configDirty.general = configDirty.personaModels = configDirty.modelRegistry = false;
 41	  mrModels = mrOriginal = mrEditingId = null;
 42	  pmModels = pmPersonas = pmAssignments = pmOriginal = null;
 43	  pmIsBuilding = false; pmCollapsed = {}; pmReplaceOpen = false;
 44	
 45	  app.innerHTML =
 46	    '<div class="page-header"><h1>Configuration</h1></div>' +
 47	    '<div class="config-tabs" id="config-tab-bar">' +
 48	      '<button class="config-tab' + (configActiveTab === 'general'       ? ' active' : '') + '" data-tab="general">General</button>' +
 49	      '<button class="config-tab' + (configActiveTab === 'personaModels' ? ' active' : '') + '" data-tab="personaModels">Persona Models</button>' +
 50	      '<button class="config-tab' + (configActiveTab === 'modelRegistry' ? ' active' : '') + '" data-tab="modelRegistry">Model Registry</button>' +
 51	    '</div>' +
 52	    '<div id="config-tab-content"></div>';
 53	
 54	  renderConfigTabContent(config, models, personas, assignments);
 55	
 56	  var tabBar = document.getElementById('config-tab-bar');
 57	  if (tabBar) {
 58	    tabBar.addEventListener('click', function (e) {
 59	      var btn = e.target.closest('button[data-tab]');
 60	      if (!btn) return;
 61	      var tab = btn.getAttribute('data-tab');
 62	      if (tab === configActiveTab) return;
 63	
 64	      /* Unsaved-changes guard */
 65	      if (configDirty[configActiveTab]) {
 66	        if (!confirm('You have unsaved changes. Discard them?')) return;
 67	        configDirty[configActiveTab] = false;
 68	        if (configActiveTab === 'modelRegistry') {
 69	          mrModels = mrOriginal = mrEditingId = null;
 70	        }
 71	        if (configActiveTab === 'personaModels') {
 72	          pmModels = pmPersonas = pmAssignments = pmOriginal = null;
 73	          pmIsBuilding = false; pmCollapsed = {}; pmReplaceOpen = false;
 74	        }
 75	      }
 76	
 77	      configActiveTab = tab;
 78	      tabBar.querySelectorAll('.config-tab').forEach(function (b) {
 79	        b.classList.toggle('active', b.getAttribute('data-tab') === tab);
 80	      });
 81	      renderConfigTabContent(config, models, personas, assignments);
 82	    });
 83	  }
 84	}
 85	
 86	/* ── Tab content dispatcher ──────────────────────────────── */
 87	
 88	function renderConfigTabContent(config, models, personas, assignments) {
 89	  var contentEl = document.getElementById('config-tab-content');
 90	  if (!contentEl) return;
 91	
 92	  if (configActiveTab === 'general') {
 93	    contentEl.innerHTML = renderGeneralTab(config);
 94	    wireGeneralTabEvents();
 95	  } else if (configActiveTab === 'personaModels') {
 96	    contentEl.innerHTML = renderPersonaModelsTab(models, personas, assignments);
 97	    pmWireEvents();
 98	  } else if (configActiveTab === 'modelRegistry') {
 99	    contentEl.innerHTML = renderModelRegistryTab(models);
100	    mrWireEvents();
101	  }
102	}
103	
104	/* ── General tab ─────────────────────────────────────────── */
105	
106	function renderGeneralTab(config) {
107	  return UI.card(null,
108	    '<form id="config-form">' +
109	      '<div class="form-group">' +
110	        '<label class="form-label" for="auto-handoff">' +
111	          '<input type="checkbox" id="auto-handoff" class="form-check" ' + (config.auto_handoff_enabled ? 'checked' : '') + '>' +
112	          ' Auto-handoff enabled' +
113	        '</label>' +
114	        '<p class="form-note">When enabled, the MCP server automatically chains work to the next agent in the workflow.</p>' +
115	      '</div>' +
116	      '<div class="form-group">' +
117	        '<label class="form-label" for="max-depth">Max handoff depth</label>' +
118	        '<input type="number" id="max-depth" class="form-control" min="1" value="' + escapeHtml(String(config.max_handoff_depth)) + '">' +
119	        '<p class="form-note">Maximum number of automatic agent handoffs before stopping.</p>' +
120	      '</div>' +
121	      '<div class="form-group">' +
122	        '<label class="form-label" for="capture-dialogues">' +
123	          '<input type="checkbox" id="capture-dialogues" class="form-check" ' + (config.capture_dialogues ? 'checked' : '') + '>' +
124	          ' Capture agent dialogues' +
125	        '</label>' +
126	        '<p class="form-note">When enabled, the orchestrator saves the full LLM conversation for each pipeline stage to the project\'s ledger as Markdown files. Changes take effect on the next orchestrator run.</p>' +
127	      '</div>' +
128	      '<div class="form-group">' +
129	        '<label class="form-label" for="auto-archive-days">Auto-archive after (days)</label>' +
130	        '<input type="number" id="auto-archive-days" class="form-control" min="0" step="1" value="' + escapeHtml(String(config.auto_archive_days != null ? config.auto_archive_days : 6)) + '">' +
131	        '<p class="form-note">Number of days after last update before a COMPLETE project is automatically archived. Set to 0 to disable auto-archiving.</p>' +
132	      '</div>' +
133	      '<div class="form-group">' +
134	        '<label class="form-label" for="ledger-root">Ledger root path</label>' +
135	        '<input type="text" id="ledger-root" class="form-control" readonly value="' + escapeHtml(config.ledger_root || '') + '">' +
136	        '<p class="form-note">Read-only. Changing this requires restarting the server with <code>--ledger-dir</code>.</p>' +
137	      '</div>' +
138	      '<button type="submit" class="btn btn-primary">Save</button>' +
139	      '<div id="config-msg"></div>' +
140	    '</form>',
141	    { style: 'max-width:560px' }
142	  );
143	}
144	
145	function wireGeneralTabEvents() {
146	  var form = document.getElementById('config-form');
147	  if (!form) return;
148	
149	  /* Mark tab dirty on any input change.
150	     Both 'change' and 'input' are intentional: checkboxes fire 'change'
151	     (not 'input'), while text/number inputs fire 'input' on each keystroke. */
152	  form.addEventListener('change', function () { configDirty.general = true; });
153	  form.addEventListener('input',  function () { configDirty.general = true; });
154	
155	  form.addEventListener('submit', function (e) {
156	    e.preventDefault();
157	    var autoHandoff = document.getElementById('auto-handoff').checked;
158	    var maxDepth = parseInt(document.getElementById('max-depth').value, 10);
159	    if (isNaN(maxDepth) || maxDepth < 1) {
160	      showError(document.getElementById('config-msg'), 'Max handoff depth must be a positive integer.');
161	      return;
162	    }
163	    var captureDialogues = document.getElementById('capture-dialogues').checked;
164	    var autoArchiveDays = parseInt(document.getElementById('auto-archive-days').value, 10);
165	    if (isNaN(autoArchiveDays) || autoArchiveDays < 0) {
166	      showError(document.getElementById('config-msg'), 'Auto-archive days must be a non-negative integer.');
167	      return;
168	    }
169	    /* ledger_root intentionally omitted (read-only) */
170	    API.updateConfig({ auto_handoff_enabled: autoHandoff, max_handoff_depth: maxDepth, capture_dialogues: captureDialogues, auto_archive_days: autoArchiveDays })
171	      .then(function () {
172	        configDirty.general = false;
173	        document.getElementById('config-msg').innerHTML = '<p class="success-banner">Configuration saved.</p>';
174	      })
175	      .catch(function (err) {
176	        showError(document.getElementById('config-msg'), 'Save failed: ' + (err.message || String(err)));
177	      });
178	  });
179	}
